with deduped as (select * from (select *, row_number() over (partition by customer_id order by started_at desc, id) as latest_rank from sessions) x where latest_rank = 1) select date_trunc('week', started_at) as week_start, count(*) filter (where browser = 'Edge') as edge_rows, size(collect_set(device)) as num_devices, sort_array(collect_set(device)) as device_list from deduped group by 1 having edge_rows < 1000 order by edge_rows nulls last;
